export class OperationProcessor {
  constructor(operations) {
      this.operations = operations;
  }

  conteo() {
      return this.operations.length;
  }

  promedio(operationType) {
      const flattenValue = (value) => {
          let sum = 0;
          if (Array.isArray(value)) {
              for (let i = 0; i < value.length; i++) {
                  sum += flattenValue(value[i].valor1 || 0);
              }
          } else if (typeof value === "number") {
              sum = value;
          }
          return sum;
      };

      let sum = 0;
      let count = 0;

      for (let i = 0; i < this.operations.length; i++) {
          const op = this.operations[i];
          if (op.operacion === operationType) {
              const valor1 = op.valor1 || 0;
              const valor2 = flattenValue(op.valor2);
              sum += (valor1 + valor2) / 2;
              count++;
          }
      }

      return count > 0 ? sum / count : 0;
  }

  max(operationType) {
      const flattenMax = (value) => {
          let maxVal = -Infinity;
          if (Array.isArray(value)) {
              for (let i = 0; i < value.length; i++) {
                  maxVal = Math.max(maxVal, flattenMax(value[i].valor1 || 0));
              }
          } else if (typeof value === "number") {
              maxVal = value;
          }
          return maxVal;
      };

      let maxValue = -Infinity;
      let found = false;

      for (let i = 0; i < this.operations.length; i++) {
          const op = this.operations[i];
          if (op.operacion === operationType) {
              const valor1 = op.valor1 || -Infinity;
              const valor2 = flattenMax(op.valor2);
              maxValue = Math.max(maxValue, valor1, valor2);
              found = true;
          }
      }

      return found ? maxValue : null;
  }

  min(operationType) {
      let minValue = Infinity;
      let found = false;

      for (let i = 0; i < this.operations.length; i++) {
          const op = this.operations[i];
          if (
              op.operacion === operationType &&
              op.valor1 !== undefined &&
              op.valor2 !== undefined
          ) {
              const valor1 = op.valor1;
              const valor2 = op.valor2;
              minValue = Math.min(minValue, valor1, valor2);
              found = true;
          }
      }

      return found ? minValue : null;
  }
}
